async function showWellFeature(p,key,layer=null){const id=String(Math.trunc(Number(p.idt_ponto??p.ponto??p.SIAGAS??p.well_id??'')));if(!id||id==='NaN'){showFeature(key,p);return;}try{lastSelection={key,p,wellId:id};if(layer)highlightWellLayer(layer);info.innerHTML='<div class="ficha-loading"><span></span><b>Carregando ficha do poço '+esc(id)+'</b><small>A consulta usa um fragmento leve da base detalhada.</small></div>';openRight();const d=await ensureWellDetail(id);if(!d){showFeature(key,p);return;}info.innerHTML=renderWellFicha(d);}catch(err){console.error(err);info.innerHTML='<div class="ficha-error"><b>Não foi possível carregar a ficha detalhada.</b><span>Tente novamente ou use a busca pelo ID SIAGAS.</span></div>';openRight();}}

