const volumeColors={'0 ou Sem Informação':'#e1e1e1','< 50.000':'#0070ff','50.000 - 250.000':'#a3ff73','250.000 - 1.000.000':'#ffff73','1.000.000 - 2.500.000':'#ffaa00','> 2.500.000':'#ff0000'};
