function normalizeSearchText(v){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
async function ensureWellSearchIndex(){
 if(wellSearchIndex)return wellSearchIndex;
 const geo=await getJSON(specs.wells.url);
 wellSearchIndex=(geo.features||[]).map(f=>{const p=f.properties||{},g=f.geometry||{};const id=String(p.idt_ponto??'');const coords=g.type==='Point'?g.coordinates:[null,null];return {id,p,lat:Number(coords[1]),lng:Number(coords[0]),search:normalizeSearchText([id,p.str_municipio,p.str_local_ponto,p.str_nome_ponto,p.str_aquifero,p.str_uso_agua].filter(valid).join(' '))};});
 return wellSearchIndex;
}
function resultSubtitle(w){const p=w.p||{};return [p.str_municipio,p.str_local_ponto,p.str_nome_ponto].filter(valid).join(' · ')||'Localização cadastral sem descrição';}
function resultMeta(w){const p=w.p||{};let a=[];if(valid(p.str_aquifero))a.push('Aquífero '+p.str_aquifero);if(valid(p.num_profundidade))a.push('Prof. '+p.num_profundidade+' m');if(valid(p.str_tipo_situacao))a.push(p.str_tipo_situacao);return a.join(' · ')||'Clique para consultar a ficha';}
async function renderWellSearch(q){
 const box=document.getElementById('wellSearchResults'); if(!box)return;
 const raw=String(q??'').trim(),nq=normalizeSearchText(raw);
 if(nq.length<2){box.innerHTML='<div class="well-search-empty">Digite pelo menos 2 caracteres. Exemplos 3500022467 · Campo Grande · Dourados · Poço A-07</div>';return;}
 const idx=await ensureWellSearchIndex();
 let hits=idx.filter(w=>w.search.includes(nq));
 hits.sort((a,b)=>{const ae=a.id===raw?0:a.id.startsWith(raw)?1:2,be=b.id===raw?0:b.id.startsWith(raw)?1:2;if(ae!==be)return ae-be;return String(a.p.str_municipio||'').localeCompare(String(b.p.str_municipio||''),'pt-BR');});
 const total=hits.length;hits=hits.slice(0,30);
 if(!hits.length){box.innerHTML='<div class="well-search-empty">Nenhum poço encontrado para <b>'+esc(raw)+'</b>. Tente ID, município, localidade ou nome.</div>';return;}
 box.innerHTML='<div class="well-search-count">'+total+' resultado'+(total===1?'':'s')+(total>30?' · mostrando os 30 primeiros':'')+'</div>'+hits.map(w=>'<button class="well-search-result" type="button" data-well-id="'+esc(w.id)+'"><span class="well-search-main"><b>SIAGAS '+esc(w.id)+'</b><span>'+esc(resultSubtitle(w))+'</span><small>'+esc(resultMeta(w))+'</small></span><span class="well-search-open">›</span></button>').join('');
 box.querySelectorAll('[data-well-id]').forEach(btn=>btn.addEventListener('click',()=>openWellById(btn.dataset.wellId,true)));
}
async function ensureWellsVisible(){
 const cb=document.querySelector('[data-layer="wells"]');if(cb&&!cb.checked)cb.checked=true;
 const layer=await ensureLayer('wells');if(!map.hasLayer(layer))layer.addTo(map);updateLegend();return layer;
}
async function openWellById(id,zoom=true){
 id=String(id??'').trim();if(!id)return false;
 const d=await ensureWellDetail(id);
 if(!d){const box=document.getElementById('wellSearchResults');if(box)box.innerHTML='<div class="well-search-empty">O ID '+esc(id)+' não possui ficha na base atual.</div>';return false;}
 await ensureWellsVisible();
 let layer=wellLayerById.get(id);
 if(!layer&&layers.wells){layers.wells.eachLayer(l=>{if(layer||!l.feature)return;const pid=String(l.feature.properties?.idt_ponto??'');if(pid===id)layer=l;});if(layer)wellLayerById.set(id,layer);}
 const lat=Number(d.summary?.latitude),lng=Number(d.summary?.longitude);
 if(layer&&layer.getLatLng){const ll=layer.getLatLng();if(zoom)map.setView(ll,Math.max(map.getZoom(),13),{animate:true});highlightWellLayer(layer);layer.bindTooltip('SIAGAS '+esc(id),{permanent:false,direction:'top',className:'well-selected-map-label'}).openTooltip();await showWellFeature(layer.feature?.properties||{idt_ponto:id},'wells',layer);}
 else{if(Number.isFinite(lat)&&Number.isFinite(lng)&&zoom)map.setView([lat,lng],Math.max(map.getZoom(),13),{animate:true});lastSelection={key:'wells',p:{idt_ponto:id},wellId:id};info.innerHTML=renderWellFicha(d);openRight();}
 statusEl.classList.remove('hide');statusEl.textContent='Poço SIAGAS '+id+' selecionado · ficha aberta';setTimeout(()=>statusEl.classList.add('hide'),1800);return true;
}
function focusWellSearch(){app.classList.remove('left-closed');setTimeout(()=>{map.invalidateSize();const el=document.getElementById('wellSearchInput');el?.scrollIntoView({behavior:'smooth',block:'center'});el?.focus();},230);}

function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));} function valid(v){return v!==null&&v!==undefined&&v!==''&&String(v).toLowerCase()!=='nan';}
async function getJSON(url){if(dataCache[url])return dataCache[url];const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${url} ${r.status}`);return dataCache[url]=await r.json();}
function openRight(){app.classList.add('right-open');setTimeout(()=>map.invalidateSize(),200)} function closeRight(){app.classList.remove('right-open');setTimeout(()=>map.invalidateSize(),200)}
function propsTable(p){const entries=Object.entries(p||{}).filter(([k,v])=>valid(v)&&!['Shape_Leng','Shape_Area'].includes(k));return `<div class="ficha-block"><h3>Atributos disponíveis</h3><div class="kv-list">${entries.map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div></div>`;}
function showFeature(key,p){lastSelection={key,p}; const titles={hydro:'Unidade hidrogeológica SGB 2024',hydroDomain:'Domínio hidrolitológico',geologyOfficial:'Unidade geológica SGB',wells:'Poço SIAGAS 2026',wellsSgb:'Poço SIAGAS/RIMAS SGB 2024',repWells:'Poço representativo SGB 2024',anpWells:'Furo ANP',potentiometry:'Potenciometria',density:'Densidade de poços',volumes:'Volumes anuais explotados',infiltration:'Capacidade de infiltração',basins:'Bacia hidrográfica',rivers:'Curso de água',waterBodies:'Massa de água',isohyets:'Isoieta',anaStations:'Estação ANA',geomorph:'Geomorfologia',g250:'Malha 250 km²',g500:'Malha 500 km²',g1000:'Malha 1000 km²'}; let h=`<div class="ficha-title"><small>${esc(titles[key]||key)}</small><h3>${esc(p.NOM_UE_AFL||p.NOME||p.nome||p.municipio||p.MUNICIPIO||p.UHE_NM||p.compartime||p.ponto||p.idt_ponto||p.SIAGAS||'Feição selecionada')}</h3></div>`; if(key==='hydro')h+=`<div class="science-chip">SGB 2024 · 1:1.000.000</div>`; if(key==='geologyOfficial')h+=`<div class="science-chip">SGB · mapa geológico 1:1.000.000 · simbologia oficial</div>`; h+=propsTable(p); info.innerHTML=h;openRight();}
function wellLabel(p){const id=p.idt_ponto??p.ponto??p.SIAGAS??p.well_id??'';const mun=p.str_municipio??p.municipio??p.MUNICIPIO??p.municipality??'';return `SIAGAS ${esc(id)}${valid(mun)?' · '+esc(mun):''}`;}
function setMapCursor(v){if(map?.getContainer)map.getContainer().style.setProperty('cursor',v||'crosshair','important');}
function setWellSelectMode(on){
 wellSelectMode=!!on;
 const bSel=document.getElementById('selectWellMode'),bMove=document.getElementById('moveMapMode');
 bSel?.classList.toggle('active',wellSelectMode); bMove?.classList.toggle('active',!wellSelectMode);
 bSel?.setAttribute('aria-pressed',String(wellSelectMode)); bMove?.setAttribute('aria-pressed',String(!wellSelectMode));
 if(!map)return;
 if(wellSelectMode){map.dragging.disable();setMapCursor('crosshair');statusEl.textContent='MODO CONSULTA · clique em um poço ou próximo dele';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);}
 else{map.dragging.enable();setMapCursor('grab');statusEl.textContent='MODO MAPA · arraste para mover';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
}
function highlightWellLayer(layer){if(!layer?.getLatLng)return; if(selectedWellHalo&&map.hasLayer(selectedWellHalo))map.removeLayer(selectedWellHalo); selectedWellHalo=L.circleMarker(layer.getLatLng(),{radius:12,color:'#ffb703',weight:4,fillColor:'#ffb703',fillOpacity:.12,interactive:false,pane:'pointsTopPane',renderer:topPointRenderer}).addTo(map);}
function nearestActiveWell(latlng,toleranceOverride=null){if(!map||!layers.wells||!map.hasLayer(layers.wells))return null;const clickPt=map.latLngToContainerPoint(latlng);let best=null,bestD=Infinity;layers.wells.eachLayer(l=>{if(!l.getLatLng)return;const d=clickPt.distanceTo(map.latLngToContainerPoint(l.getLatLng()));if(d<bestD){bestD=d;best=l;}});const z=map.getZoom();const tolerance=toleranceOverride??(z<=6?24:z<=8?30:z<=11?38:44);return best&&bestD<=tolerance?{layer:best,distancePx:bestD}:null;}
async function openNearestWell(latlng){const hit=nearestActiveWell(latlng);if(!hit){statusEl.textContent='Nenhum poço próximo · use a busca ou clique mais perto';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);return false;}const p=hit.layer.feature?.properties||{};highlightWellLayer(hit.layer);await showWellFeature(p,'wells',hit.layer);return true;}
