function pointFor(key,f,latlng){if(isEvidenceKey(key)||isVerticalTemporalKey(key)){const e=evidenceInfo[key]||verticalTemporalInfo[key]||{color:'#3A7CA5'};return L.circleMarker(latlng,{radius:key==='e09'?5.4:4.4,color:'#ffffff',weight:1.15,fillColor:e.color,fillOpacity:.92,pane:'pointsTopPane',renderer:topPointRenderer});}if(key==='wells')return L.circleMarker(latlng,{radius:4.2,color:'#fff',weight:1.1,fillColor:'#0077b6',fillOpacity:.92,pane:'pointsPane',renderer:wellRenderer});if(key==='wellsSgb')return L.circleMarker(latlng,{radius:3.8,color:'#fff',weight:1,fillColor:'#202020',fillOpacity:.8,pane:'pointsPane',renderer:wellRenderer});if(key==='repWells')return L.circleMarker(latlng,{radius:6,color:'#fff',weight:1.3,fillColor:'#d62828',fillOpacity:1,pane:'pointsTopPane',renderer:topPointRenderer});if(key==='anpWells')return L.circleMarker(latlng,{radius:5,color:'#fff',weight:1,fillColor:'#f28e2b',fillOpacity:1,pane:'pointsTopPane',renderer:topPointRenderer});if(key==='anaStations')return L.circleMarker(latlng,{radius:3.2,color:'#fff',weight:.8,fillColor:'#00a8a8',fillOpacity:.85,pane:'pointsPane',renderer:wellRenderer});return L.circleMarker(latlng,{radius:3,color:'#fff',weight:1,fillColor:'#3a7ca5',fillOpacity:.8,pane:'pointsPane',renderer:wellRenderer});}
