function ekMetricMeta(scale){return ekMeta?.scales?.[String(scale)]?.[activeEKMetric]||{quantiles:[]};}
function ekColor(v,q,pal){if(v===null||v===undefined||Number.isNaN(Number(v)))return 'transparent';let i=0;for(const x of(q||[]))if(Number(v)>Number(x))i++;return pal[Math.min(i,pal.length-1)];}
function effectiveKnowledgeStyle(f,key){const p=f.properties||{},scale=key.replace('ek',''),m=ekMetricDef(),meta=ekMetricMeta(scale),v=p[activeEKMetric],defined=v!==null&&v!==undefined&&Number.isFinite(Number(v))&&(activeEKMetric==='spatial_gap_E01_p90_km'||Number(p.n_wells)>0);return{pane:'gridPane',color:'#4b545d',weight:.8,opacity:.9,fillColor:defined?ekColor(v,meta.quantiles,m.palette):'transparent',fillOpacity:defined?.73:0};}
function clearEKHighlight(){if(selectedEKLayer&&selectedEKKey&&selectedEKLayer.feature){try{selectedEKLayer.setStyle(effectiveKnowledgeStyle(selectedEKLayer.feature,selectedEKKey));}catch(e){}}selectedEKLayer=null;selectedEKKey=null;}
function highlightEKCell(layer,key){if(selectedEKLayer&&selectedEKLayer!==layer&&selectedEKKey&&selectedEKLayer.feature){try{selectedEKLayer.setStyle(effectiveKnowledgeStyle(selectedEKLayer.feature,selectedEKKey));}catch(e){}}selectedEKLayer=layer;selectedEKKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.82});if(layer?.bringToFront)layer.bringToFront();}
function ekNum(v,d=1,s=''){return valid(v)&&Number.isFinite(Number(v))?Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})+s:null;}
function effectiveKnowledgeFicha(p){const m=ekMetricDef(),suffix=activeEKMetric.endsWith('_pct')?'%':activeEKMetric.endsWith('_km')?' km':'';return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">Conhecimento hidrogeológico efetivo · ${esc(p.scale_km2)} km²</div><div class="well-badges"><span class="well-badge unknown">NOVE DIMENSÕES SEPARADAS</span><span class="well-badge review">SEM ÍNDICE · SEM PRIORIDADE</span></div></div><section class="ficha-section"><h4>Métrica selecionada</h4><div class="ficha-grid">${frow(m.label,ekNum(p[activeEKMetric],2,suffix),'derived')}${frow('Poços canônicos na célula',p.n_wells,'derived')}${frow('Estado de análise',p.analysis_status,'derived')}</div></section><section class="ficha-section"><h4>Vetor não agregado</h4><div class="ficha-grid">${frow('Espacial',p.spatial_state,'derived')}${frow('Hidroestratigráfica',p.hydrostrat_state,'derived')}${frow('Vertical',p.vertical_state,'derived')}${frow('Hidráulica',p.hydraulic_state,'derived')}${frow('Hidroquímica',p.hydrochemical_state,'derived')}${frow('Temporal',p.temporal_state,'derived')}${frow('Independência',p.independence_state,'derived')}${frow('Qualidade documental',p.documentary_state,'derived')}${frow('Incerteza',p.uncertainty_state,'derived')}</div><div class="ficha-note">Os estados não são somados. UNKNOWN não é zero.</div></section><section class="ficha-section"><h4>Espacial e hidroestratigráfica</h4><div class="ficha-grid">${frow('Lacuna espacial E01 P90',ekNum(p.spatial_gap_E01_p90_km,2,' km'),'derived')}${frow('Coordenadas em revisão',ekNum(p.spatial_coordinate_review_pct,1,'%'),'derived')}${frow('Unidades na célula',p.hydrostrat_units_n,'derived')}${frow('Unidade dominante',p.hydrostrat_dominant_unit,'derived')}${frow('Dominância da unidade',ekNum(p.hydrostrat_dominant_unit_pct,1,'%'),'derived')}${frow('Revisão hidroestratigráfica',ekNum(p.hydrostrat_review_pct,1,'%'),'derived')}${frow('UNKNOWN hidroestratigráfico',ekNum(p.hydrostrat_unknown_pct,1,'%'),'derived')}</div></section><section class="ficha-section"><h4>Vertical e hidráulica</h4><div class="ficha-grid">${frow('Profundidade positiva',ekNum(p.vertical_depth_positive_pct,1,'%'),'derived')}${frow('Metadado vertical presente',ekNum(p.vertical_metadata_present_pct,1,'%'),'derived')}${frow('Intervalo captado demonstrado',p.vertical_capture_interval_demonstrated_n,'derived')}${frow('Ensaio cadastrado',ekNum(p.hydraulic_test_registered_pct,1,'%'),'derived')}${frow('Ensaio com metadados mínimos',ekNum(p.hydraulic_test_minimum_metadata_pct,1,'%'),'derived')}${frow('Transmissividade informada',ekNum(p.hydraulic_transmissivity_reported_pct,1,'%'),'derived')}</div><div class="ficha-note">Profundidade total não é intervalo captado. Transmissividade informada não é parâmetro validado.</div></section><section class="ficha-section"><h4>Hidroquímica e temporal</h4><div class="ficha-grid">${frow('Evidência hidroquímica parcial',ekNum(p.hydrochemical_partial_evidence_pct,1,'%'),'derived')}${frow('Evidência hidroquímica datada',ekNum(p.hydrochemical_dated_pct,1,'%'),'derived')}${frow('Tipos de parâmetro',p.hydrochemical_parameter_types_n,'derived')}${frow('Qualquer evidência datada',ekNum(p.temporal_any_dated_pct,1,'%'),'derived')}${frow('Múltiplos domínios datados',ekNum(p.temporal_multiple_domains_pct,1,'%'),'derived')}${frow('Série temporal demonstrada',p.temporal_time_series_demonstrated_n,'derived')}</div><div class="ficha-note">Evidência parcial não demonstra painel comparável. Evento datado não forma série.</div></section><section class="ficha-section"><h4>Independência, qualidade e incerteza</h4><div class="ficha-grid">${frow('Candidatos a duplicidade',ekNum(p.independence_duplicate_candidate_pct,1,'%'),'derived')}${frow('Vizinho a menos de 500 m',ekNum(p.independence_nn_lt_500m_pct,1,'%'),'derived')}${frow('Poços com alertas',ekNum(p.documentary_flagged_wells_pct,1,'%'),'derived')}${frow('Poços com valor inválido',ekNum(p.documentary_invalid_wells_pct,1,'%'),'derived')}${frow('Domínios documentais · mediana',ekNum(p.documentary_domains_median,1,''),'derived')}${frow('Códigos de incerteza',String(p.uncertainty_codes||'').split('|').join(' · '),'derived')}</div><div class="ficha-note">Proximidade e duplicidade são contexto de revisão. Não demonstram independência hidrogeológica.</div><p><a href="guia-resultados.html#conhecimento-efetivo" target="_blank">Como ler a matriz</a> · <a href="metodologia-conhecimento-efetivo.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function openEffectiveKnowledgeFeature(p,layer,key){highlightEKCell(layer,key);lastSelection={key,p,effectiveKnowledge:true};info.innerHTML=effectiveKnowledgeFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · conhecimento hidrogeológico efetivo`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
async function showEffectiveKnowledge(){const scale=document.getElementById('ekScale')?.value||'250',metric=document.getElementById('ekMetric')?.value||'n_wells',key='ek'+scale;await ensureEKMeta();activeEKMetric=metric;clearEKHighlight();if(activeIRKey)hideIndependence();if(activeVTKey)hideVerticalTemporal();if(activeStratifiedKey)hideStratified();if(activeScaleStudyKey)hideScaleStudy();if(activeSpatialKey)hideSpatialStructure();if(activeGridEvidenceKey)hideGridEvidence();if(activeEKKey&&activeEKKey!==key&&layers[activeEKKey])map.removeLayer(layers[activeEKKey]);activeEKKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>effectiveKnowledgeStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='CONHECIMENTO EFETIVO · clique em uma célula';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);updateLegend();}
function hideEffectiveKnowledge(){if(activeEKKey&&layers[activeEKKey]&&map.hasLayer(layers[activeEKKey]))map.removeLayer(layers[activeEKKey]);clearEKHighlight();activeEKKey=null;updateLegend();}

let activeQSKey=null,activeQSQuestion='Q01',selectedQSLayer=null,selectedQSKey=null;
const updateLegendBeforeQS=updateLegend;
updateLegend=function(){updateLegendBeforeQS();if(activeQSKey&&layers[activeQSKey]&&map.hasLayer(layers[activeQSKey])){const sc=activeQSKey.replace('qs',''),meta=questionInfo[activeQSQuestion]||{name:activeQSQuestion};document.getElementById('legendCard').insertAdjacentHTML('beforeend',`<div class="legend-section"><div class="legend-title">Suficiência por pergunta · ${sc} km²</div><div class="legend-note"><b>${activeQSQuestion} · ${esc(meta.name)}</b></div><div class="legend-row"><span class="count-swatch" style="background:#cbd5df"></span>Sem poços no conjunto auditado</div><div class="legend-row"><span class="count-swatch" style="background:#7b61a8"></span>Sem evidência direta da pergunta</div><div class="legend-row"><span class="count-swatch" style="background:#e69a35"></span>Somente evidência parcial</div><div class="legend-row"><span class="count-swatch" style="background:#2f855a"></span>Mínimo documental local demonstrado</div><div class="legend-note">Categorias documentais. Não representam potencial, prioridade ou representatividade territorial.</div></div>`);}};
function qsPrefix(){return activeQSQuestion.toLowerCase();}
function qsState(p){return String(p?.[`${qsPrefix()}_cell_documentary_state`]||'UNKNOWN');}
function questionSufficiencyStyle(f,key){const p=f.properties||{},state=qsState(p);let fill='#9aa7b3',opacity=.42;if(state==='UNKNOWN_SEM_POCOS_NO_CONJUNTO_AUDITADO'){fill='#cbd5df';opacity=.2;}else if(state==='UNKNOWN_SEM_EVIDENCIA_DIRETA_DA_PERGUNTA'){fill='#7b61a8';opacity=.62;}else if(state==='SOMENTE_EVIDENCIA_PARCIAL'){fill='#e69a35';opacity=.7;}else if(state==='MINIMO_DOCUMENTAL_DEMONSTRADO'){fill='#2f855a';opacity=.76;}return{pane:'gridPane',color:'#4b545d',weight:.85,opacity:.92,fillColor:fill,fillOpacity:opacity};}
function clearQSHighlight(){if(selectedQSLayer&&selectedQSKey&&selectedQSLayer.feature){try{selectedQSLayer.setStyle(questionSufficiencyStyle(selectedQSLayer.feature,selectedQSKey));}catch(error){}}selectedQSLayer=null;selectedQSKey=null;}
function highlightQSCell(layer,key){if(selectedQSLayer&&selectedQSLayer!==layer&&selectedQSKey&&selectedQSLayer.feature){try{selectedQSLayer.setStyle(questionSufficiencyStyle(selectedQSLayer.feature,selectedQSKey));}catch(error){}}selectedQSLayer=layer;selectedQSKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.84});if(layer?.bringToFront)layer.bringToFront();}
function questionSufficiencyFicha(p){const code=activeQSQuestion,meta=questionInfo[code]||{name:code},prefix=code.toLowerCase(),state=p[`${prefix}_cell_documentary_state`],representativeness=p[`${prefix}_cell_representativeness_state`],blockers=questionBlockers(p[`${prefix}_top_blocking_requirements`]);return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">${code} · ${esc(meta.name)} · ${esc(p.scale_km2)} km²</div><div class="well-badges"><span class="well-badge review">${esc(questionStateLabel(state))}</span><span class="well-badge unknown">REPRESENTATIVIDADE UNKNOWN</span></div></div><section class="ficha-section"><h4>Estado documental local</h4><div class="ficha-grid">${frow('Poços canônicos na célula',p.n_wells,'derived')}${frow('Evidência direta',p[`${prefix}_direct_evidence_n`],'derived')}${frow('Mínimo documental completo',p[`${prefix}_minimum_documentary_n`],'derived')}${frow('Evidência parcial',p[`${prefix}_partial_evidence_n`],'derived')}${frow('Evidência com revisão',p[`${prefix}_review_evidence_n`],'derived')}${frow('Evidência UNKNOWN',p[`${prefix}_unknown_evidence_n`],'derived')}${frow('Estado local',questionStateLabel(state),'derived')}${frow('Representatividade',questionStateLabel(representativeness),'derived')}</div></section><section class="ficha-section"><h4>Requisitos bloqueantes mais frequentes</h4>${blockers.length?`<div class="quality-list">${blockers.map(item=>`<div class="quality-item"><b>${esc(item.code)} · ${esc(item.label)}</b><br>${Number(item.count||0).toLocaleString('pt-BR')} poço${Number(item.count)===1?'':'s'} da célula não demonstram o requisito.</div>`).join('')}</div>`:'<div class="ficha-note">A célula não contém poços no conjunto auditado ou não possui bloqueios contabilizáveis.</div>'}</section><section class="ficha-section"><h4>Contexto hidroestratigráfico</h4><div class="ficha-grid">${frow('Unidade dominante',p.hydrostrat_dominant_unit,'derived')}${frow('Dominância da unidade',valid(p.hydrostrat_dominant_unit_pct)?Number(p.hydrostrat_dominant_unit_pct).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':null,'derived')}${frow('Domínio dominante',p.hydrostrat_dominant_domain,'derived')}${frow('Dominância do domínio',valid(p.hydrostrat_dominant_domain_pct)?Number(p.hydrostrat_dominant_domain_pct).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':null,'derived')}</div><div class="ficha-note">A unidade dominante não substitui a hidroestratigrafia documentada de cada poço.</div></section><section class="ficha-section"><h4>Leitura obrigatória</h4><div class="ficha-note">O mínimo documental é conjuntivo e específico desta pergunta. Contar requisitos atendidos não cria score. Uma célula com registros completos não é automaticamente representativa do território. Nenhum resultado desta ficha equivale a potencial aquífero ou prioridade final.</div><p><a href="guia-resultados.html#suficiencia-pergunta" target="_blank">Como ler estes resultados</a> · <a href="metodologia-suficiencia-pergunta.html" target="_blank">Metodologia completa da V2.4</a></p></section></div>`;}
function openQuestionSufficiencyFeature(p,layer,key){highlightQSCell(layer,key);lastSelection={key,p,questionSufficiency:true};info.innerHTML=questionSufficiencyFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · ${activeQSQuestion} · suficiência documental`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2000);}
async function showQuestionSufficiency(){const scale=document.getElementById('qsScale')?.value||'250',question=document.getElementById('qsQuestion')?.value||'Q01',key='qs'+scale;activeQSQuestion=question;clearQSHighlight();if(activeEKKey)hideEffectiveKnowledge();if(activeIRKey)hideIndependence();if(activeVTKey)hideVerticalTemporal();if(activeStratifiedKey)hideStratified();if(activeScaleStudyKey)hideScaleStudy();if(activeSpatialKey)hideSpatialStructure();if(activeGridEvidenceKey)hideGridEvidence();if(activeQSKey&&activeQSKey!==key&&layers[activeQSKey])map.removeLayer(layers[activeQSKey]);activeQSKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>questionSufficiencyStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent=`${question} · SUFICIÊNCIA POR PERGUNTA · clique em uma célula`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2400);updateLegend();}
