let activeSSKey=null,activeSSQuestion='Q01',activeSSMetric='cell_state_code',selectedSSLayer=null,selectedSSKey=null;
const ssMetricInfo={cell_state_code:{label:'Estado documental local',unit:'',family:'state'},direct_evidence_n:{label:'Registros com evidência direta',unit:'',family:'count'},cross_scale_exact_pct:{label:'Concordância exata entre escalas',unit:'%',family:'percent'},origin_exact_pct:{label:'Concordância exata entre origens',unit:'%',family:'percent'},n_wells:{label:'Poços do conjunto auditado',unit:'',family:'count'},hydro_surface_units_n:{label:'Unidades hidrogeológicas superficiais no suporte',unit:'',family:'hydro'}};
function ssPrefix(){return activeSSQuestion.toLowerCase();}
function ssProperty(){if(activeSSMetric==='cell_state_code')return `${ssPrefix()}_cell_state_code`;if(activeSSMetric==='direct_evidence_n')return `${ssPrefix()}_direct_evidence_n`;if(activeSSMetric==='cross_scale_exact_pct')return `${ssPrefix()}_cross_scale_exact_pct`;if(activeSSMetric==='origin_exact_pct')return `${ssPrefix()}_origin_exact_pct`;return activeSSMetric;}
function ssColor(value,family){if(value===null||value===undefined||!Number.isFinite(Number(value)))return 'transparent';const v=Number(value);if(family==='state')return v===0?'#cbd5df':v===1?'#7b61a8':'#27856b';if(family==='percent')return v<25?'#f1f5f9':v<50?'#d7e7ec':v<75?'#a8d5d0':v<100?'#65b7a8':'#197665';if(family==='hydro')return v===0?'transparent':v===1?'#9ecae1':v===2?'#4d7ea8':'#684a8a';return v===0?'transparent':v===1?'#d7e7ec':v<=3?'#a8d5d0':v<=10?'#65b7a8':'#197665';}
function stabilitySensitivityStyle(f){const p=f.properties||{},meta=ssMetricInfo[activeSSMetric],value=p[ssProperty()],defined=value!==null&&value!==undefined&&Number.isFinite(Number(value));return{pane:'gridPane',color:'#425762',weight:.85,opacity:.92,fillColor:defined?ssColor(value,meta.family):'transparent',fillOpacity:defined?.74:0};}
function clearSSHighlight(){if(selectedSSLayer&&selectedSSLayer.feature){try{selectedSSLayer.setStyle(stabilitySensitivityStyle(selectedSSLayer.feature));}catch(error){}}selectedSSLayer=null;selectedSSKey=null;}
function highlightSSCell(layer,key){if(selectedSSLayer&&selectedSSLayer!==layer&&selectedSSLayer.feature){try{selectedSSLayer.setStyle(stabilitySensitivityStyle(selectedSSLayer.feature));}catch(error){}}selectedSSLayer=layer;selectedSSKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.86});layer?.bringToFront?.();}
function ssPercent(value){return valid(value)&&Number.isFinite(Number(value))?Number(value).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':null;}
function stabilitySensitivityFicha(p){const prefix=ssPrefix(),meta=questionInfo[activeSSQuestion]||{name:activeSSQuestion},blockers=questionBlockers(p[`${prefix}_top_blocking_requirements`]);return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">${activeSSQuestion} · ${esc(meta.name)} · ${esc(p.scale_km2)} km²</div><div class="well-badges"><span class="well-badge review">ESTABILIDADE DESCRITIVA</span><span class="well-badge unknown">SEM ESCALA OU ORIGEM FINAL</span></div></div><section class="ficha-section"><h4>Estado e suporte local</h4><div class="ficha-grid">${frow('Estado documental',p[`${prefix}_cell_state_label`],'derived')}${frow('Poços na célula',p.n_wells,'derived')}${frow('Evidência direta',p[`${prefix}_direct_evidence_n`],'derived')}${frow('Pontos fixos de suporte',p.support_points_n,'derived')}${frow('Concordância entre escalas',ssPercent(p[`${prefix}_cross_scale_exact_pct`]),'derived')}${frow('Concordância entre origens',ssPercent(p[`${prefix}_origin_exact_pct`]),'derived')}</div></section><section class="ficha-section"><h4>Contexto hidrogeológico superficial</h4><div class="ficha-grid">${frow('Unidades no suporte',p.hydro_surface_units_n,'derived')}${frow('Domínios no suporte',p.hydro_surface_domains_n,'derived')}${frow('Estado do contexto',p.hydro_context_state,'derived')}${frow('Unidade dominante',p.hydro_dominant_unit,'derived')}${frow('Domínio dominante',p.hydro_dominant_domain,'derived')}</div><div class="ficha-note">O contexto usa pontos fixos classificados pelo SGB 2024. Não é fração exata de área nem estrutura vertical.</div></section><section class="ficha-section"><h4>Bloqueios documentais locais</h4>${blockers.length?`<div class="quality-list">${blockers.map(item=>`<div class="quality-item"><b>${esc(item.code)} · ${esc(item.label)}</b><br>${Number(item.count||0).toLocaleString('pt-BR')} ocorrências na célula.</div>`).join('')}</div>`:'<div class="ficha-note">Sem bloqueios contabilizáveis ou sem poços no conjunto auditado.</div>'}</section><section class="ficha-section"><h4>Leitura obrigatória</h4><div class="ficha-note">Mudança de estado entre escalas ou origens descreve sensibilidade da agregação. Não autoriza escolher uma escala, inferir ausência física, calcular representatividade ou gerar prioridade.</div><p><a href="metodologia-estabilidade-sensibilidade.html" target="_blank">Metodologia completa da V2.5</a></p></section></div>`;}
function openStabilitySensitivityFeature(p,layer,key){highlightSSCell(layer,key);lastSelection={key,p,stabilitySensitivity:true};info.innerHTML=stabilitySensitivityFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · estabilidade e sensibilidade`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);}
async function ensureSSLayer(key,scale){if(layers[key])return layers[key];const data=await getJSON(`data/stability_sensitivity/stability_sensitivity_${scale}km2.geojson`);const layer=L.geoJSON(data,{pane:'gridPane',style:stabilitySensitivityStyle,onEachFeature:(feature,item)=>{item.on('mouseover',()=>{setMapCursor('pointer');if(item!==selectedSSLayer)item.setStyle({weight:2,color:'#243f50',opacity:1});});item.on('mouseout',()=>{setMapCursor(wellSelectMode?'crosshair':'grab');if(item!==selectedSSLayer)item.setStyle(stabilitySensitivityStyle(feature));});item.on('click',event=>{L.DomEvent.stopPropagation(event);openStabilitySensitivityFeature(feature.properties||{},item,key);});}});layers[key]=layer;return layer;}
async function showStabilitySensitivity(){const scale=document.getElementById('ssScale')?.value||'250';activeSSQuestion=document.getElementById('ssQuestion')?.value||'Q01';activeSSMetric=document.getElementById('ssMetric')?.value||'cell_state_code';const key='ss'+scale;clearSSHighlight();hideQuestionSufficiency();hideEffectiveKnowledge();hideIndependence();hideVerticalTemporal();hideStratified();hideScaleStudy();hideSpatialStructure();hideGridEvidence();if(activeSSKey&&activeSSKey!==key&&layers[activeSSKey])map.removeLayer(layers[activeSSKey]);activeSSKey=key;const layer=await ensureSSLayer(key,scale);layer.setStyle(stabilitySensitivityStyle);if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent=`${activeSSQuestion} · ESTABILIDADE E SENSIBILIDADE · clique em uma célula`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2400);updateLegend();}
function hideStabilitySensitivity(){if(activeSSKey&&layers[activeSSKey]&&map.hasLayer(layers[activeSSKey]))map.removeLayer(layers[activeSSKey]);clearSSHighlight();activeSSKey=null;updateLegend();}
const updateLegendBeforeSS=updateLegend;
updateLegend=function(){updateLegendBeforeSS();if(activeSSKey&&layers[activeSSKey]&&map.hasLayer(layers[activeSSKey])){const scale=activeSSKey.replace('ss',''),meta=ssMetricInfo[activeSSMetric],rows=meta.family==='state'?`<div class="legend-row"><span class="count-swatch" style="background:#cbd5df"></span>Sem poços no conjunto</div><div class="legend-row"><span class="count-swatch" style="background:#7b61a8"></span>Poços sem evidência direta</div><div class="legend-row"><span class="count-swatch" style="background:#27856b"></span>Evidência direta presente</div>`:`<div class="legend-row"><span class="count-swatch" style="background:#f1f5f9"></span>classe inferior</div><div class="legend-row"><span class="count-swatch" style="background:#a8d5d0"></span>classe intermediária</div><div class="legend-row"><span class="count-swatch" style="background:#197665"></span>classe superior</div>`;document.getElementById('legendCard').insertAdjacentHTML('beforeend',`<div class="legend-section"><div class="legend-title">Estabilidade e sensibilidade · ${scale} km²</div><div class="legend-note"><b>${activeSSQuestion} · ${esc(meta.label)}</b></div>${rows}<div class="legend-note">Classes descritivas. Não representam prioridade, potencial ou escala final.</div></div>`);}};
