let activeRPKey=null,activeRPQuestion='Q01',activeRPMetric='priority_code',selectedRPLayer=null,selectedRPKey=null;
const rpPalette={0:'#7C8793',1:'#B2182B',2:'#F28E2B',3:'#7B4AB4',4:'#1B9E9A',5:'#2E8B57'};
const rpPriorityLabels={0:'UNKNOWN · não classificável',1:'P1 · crítica',2:'P2 · alta',3:'P3 · moderada',4:'P4 · baixa',5:'P5 · suficiência documental'};
const rpConfidenceLabels={0:'UNKNOWN · não classificável',1:'C1 · muito baixa',2:'C2 · baixa',3:'C3 · moderada',4:'C4 · alta',5:'C5 · muito alta'};
const rpMetricInfo={priority_code:{label:'Prioridade de investigação',family:'class'},confidence_code:{label:'Confiança da classificação',family:'class'},cross_scale_priority_exact_pct:{label:'Concordância entre escalas',family:'percent'},origin_priority_exact_pct:{label:'Concordância entre origens',family:'percent'},direct_evidence_n:{label:'Poços com evidência direta',family:'count'},context_gate_n:{label:'Poços com contexto mínimo',family:'count'},fully_blocked_requirements_n:{label:'Requisitos bloqueados em todos os poços',family:'count'},n_wells:{label:'Poços do conjunto auditado',family:'count'}};
function rpPrefix(){return activeRPQuestion.toLowerCase();}
function rpProperty(){return activeRPMetric==='n_wells'?'n_wells':`${rpPrefix()}_${activeRPMetric}`;}
function rpValue(p){return p?.[rpProperty()];}
function rpColor(value,family){if(value===null||value===undefined||!Number.isFinite(Number(value)))return 'transparent';const v=Number(value);if(family==='class')return rpPalette[Math.max(0,Math.min(5,Math.round(v)))]||rpPalette[0];if(family==='percent')return v===0?rpPalette[1]:v<50?rpPalette[2]:v<100?rpPalette[3]:v===100?rpPalette[5]:rpPalette[4];return v===0?'transparent':v===1?rpPalette[4]:v<=3?rpPalette[3]:v<=10?rpPalette[2]:rpPalette[1];}
function researchPriorityStyle(feature){const p=feature.properties||{},meta=rpMetricInfo[activeRPMetric],value=rpValue(p),defined=value!==null&&value!==undefined&&Number.isFinite(Number(value));return{pane:'gridPane',color:'#425762',weight:.85,opacity:.94,fillColor:defined?rpColor(value,meta.family):'transparent',fillOpacity:defined?.78:0};}
function clearRPHighlight(){if(selectedRPLayer&&selectedRPLayer.feature){try{selectedRPLayer.setStyle(researchPriorityStyle(selectedRPLayer.feature));}catch(error){}}selectedRPLayer=null;selectedRPKey=null;}
function highlightRPCell(layer,key){if(selectedRPLayer&&selectedRPLayer!==layer&&selectedRPLayer.feature){try{selectedRPLayer.setStyle(researchPriorityStyle(selectedRPLayer.feature));}catch(error){}}selectedRPLayer=layer;selectedRPKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.88});layer?.bringToFront?.();}
function rpPct(value){return valid(value)&&Number.isFinite(Number(value))?Number(value).toLocaleString('pt-BR',{maximumFractionDigits:1})+'%':null;}
function rpActions(value){return String(value||'').split('|').filter(Boolean);}
function researchPriorityFicha(p){const prefix=rpPrefix(),meta=questionInfo[activeRPQuestion]||{name:activeRPQuestion},priority=Number(p[`${prefix}_priority_code`]||0),confidence=Number(p[`${prefix}_confidence_code`]||0),blockers=questionBlockers(p[`${prefix}_top_blocking_requirements`]),actions=rpActions(p[`${prefix}_recommended_actions`]);return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">${activeRPQuestion} · ${esc(meta.name)} · ${esc(p.scale_km2)} km²</div><div class="well-badges"><span class="well-badge priority-p${priority}">${esc(rpPriorityLabels[priority])}</span><span class="well-badge confidence-c${confidence}">${esc(rpConfidenceLabels[confidence])}</span></div></div><section class="ficha-section"><h4>Prioridade e confiança separadas</h4><div class="ficha-grid">${frow('Prioridade por pergunta',rpPriorityLabels[priority],'derived')}${frow('Confiança',rpConfidenceLabels[confidence],'derived')}${frow('Poços considerados',p.n_wells,'derived')}${frow('Evidência direta',p[`${prefix}_direct_evidence_n`],'derived')}${frow('Contexto mínimo',p[`${prefix}_context_gate_n`],'derived')}${frow('Mínimo documental completo',p[`${prefix}_minimum_documentary_n`],'derived')}${frow('Registros em revisão',p[`${prefix}_review_evidence_n`],'derived')}${frow('Requisitos totalmente bloqueados',p[`${prefix}_fully_blocked_requirements_n`],'derived')}</div></section><section class="ficha-section"><h4>Estabilidade da classificação</h4><div class="ficha-grid">${frow('Concordância entre cinco escalas',rpPct(p[`${prefix}_cross_scale_priority_exact_pct`]),'derived')}${frow('Concordância entre quatro origens',rpPct(p[`${prefix}_origin_priority_exact_pct`]),'derived')}${frow('Pontos fixos de suporte',p.support_points_n,'derived')}${frow('Independência',p[`${prefix}_independence_state`],'derived')}${frow('Representatividade',p[`${prefix}_representativeness_state`],'derived')}</div><div class="ficha-note">A confiança descreve estabilidade da classe. Não substitui a prioridade e não demonstra representatividade territorial.</div></section><section class="ficha-section"><h4>Principais carências</h4>${blockers.length?`<div class="quality-list">${blockers.map(item=>`<div class="quality-item"><b>${esc(item.code)} · ${esc(item.label)}</b><br>${Number(item.count||0).toLocaleString('pt-BR')} poço${Number(item.count)===1?'':'s'} não demonstra${Number(item.count)===1?'':'m'} o requisito.</div>`).join('')}</div>`:'<div class="ficha-note">Não há poço do conjunto auditado ou não há bloqueio contabilizável.</div>'}</section><section class="ficha-section"><h4>Ações recomendadas</h4>${actions.length?`<ol class="priority-actions">${actions.map(item=>`<li>${esc(item)}</li>`).join('')}</ol>`:'<div class="ficha-note">Sem recomendação operacional porque a prioridade permanece UNKNOWN.</div>'}<div class="ficha-note">Recomendação para aquisição ou revisão de informação. Não é autorização de obra, captação ou exploração.</div></section><section class="ficha-section"><h4>Limites obrigatórios</h4><div class="ficha-note">Esta é uma prioridade experimental derivada do déficit documental demonstrado no conjunto PIH MS V2.5. Não é potencial aquífero, prioridade absoluta, prioridade integrada ou prova de ausência física. UNKNOWN não é convertido em prioridade.</div><p><a href="metodologia-prioridade-investigacao.html" target="_blank">Metodologia completa da V2.6</a></p></section></div>`;}
function openResearchPriorityFeature(p,layer,key){highlightRPCell(layer,key);lastSelection={key,p,researchPriority:true};info.innerHTML=researchPriorityFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · prioridade por pergunta`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);}
async function ensureRPLayer(key,scale){if(layers[key])return layers[key];const data=await getJSON(`data/research_priority/research_priority_${scale}km2.geojson`);const layer=L.geoJSON(data,{pane:'gridPane',style:researchPriorityStyle,onEachFeature:(feature,item)=>{item.on('mouseover',()=>{setMapCursor('pointer');if(item!==selectedRPLayer)item.setStyle({weight:2,color:'#243f50',opacity:1});});item.on('mouseout',()=>{setMapCursor(wellSelectMode?'crosshair':'grab');if(item!==selectedRPLayer)item.setStyle(researchPriorityStyle(feature));});item.on('click',event=>{L.DomEvent.stopPropagation(event);openResearchPriorityFeature(feature.properties||{},item,key);});}});layers[key]=layer;return layer;}
async function showResearchPriority(){const scale=document.getElementById('rpScale')?.value||'250';activeRPQuestion=document.getElementById('rpQuestion')?.value||'Q01';activeRPMetric=document.getElementById('rpMetric')?.value||'priority_code';const key='rp'+scale;clearRPHighlight();hideStabilitySensitivity();hideQuestionSufficiency();hideEffectiveKnowledge();hideIndependence();hideVerticalTemporal();hideStratified();hideScaleStudy();hideSpatialStructure();hideGridEvidence();if(activeRPKey&&activeRPKey!==key&&layers[activeRPKey])map.removeLayer(layers[activeRPKey]);activeRPKey=key;const layer=await ensureRPLayer(key,scale);layer.setStyle(researchPriorityStyle);if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent=`${activeRPQuestion} · PRIORIDADE EXPERIMENTAL · clique em uma célula`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2400);updateLegend();}
