const updateLegendBeforeRP=updateLegend;
updateLegend=function(){updateLegendBeforeRP();if(activeRPKey&&layers[activeRPKey]&&map.hasLayer(layers[activeRPKey])){const scale=activeRPKey.replace('rp',''),meta=rpMetricInfo[activeRPMetric];const rows=activeRPMetric==='priority_code'?`<div class="legend-row"><span class="count-swatch" style="background:${rpPalette[0]}"></span>UNKNOWN · não classificável</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[1]}"></span>P1 · crítica</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[2]}"></span>P2 · alta</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[3]}"></span>P3 · moderada</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[4]}"></span>P4 · baixa</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[5]}"></span>P5 · suficiência documental</div>`:activeRPMetric==='confidence_code'?`<div class="legend-row"><span class="count-swatch" style="background:${rpPalette[0]}"></span>UNKNOWN</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[1]}"></span>C1 · muito baixa</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[2]}"></span>C2 · baixa</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[3]}"></span>C3 · moderada</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[4]}"></span>C4 · alta</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[5]}"></span>C5 · muito alta</div>`:`<div class="legend-row"><span class="count-swatch" style="background:${rpPalette[1]}"></span>classe inferior</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[3]}"></span>classe intermediária</div><div class="legend-row"><span class="count-swatch" style="background:${rpPalette[5]}"></span>classe superior</div>`;document.getElementById('legendCard').insertAdjacentHTML('beforeend',`<div class="legend-section"><div class="legend-title">Prioridade por pergunta · ${scale} km²</div><div class="legend-note"><b>${activeRPQuestion} · ${esc(meta.label)}</b></div>${rows}<div class="legend-note">Prioridade e confiança permanecem separadas. Sem prioridade integrada.</div></div>`);}};
