 const docsGrid=document.querySelector('#docsModal .docs-link-grid');if(docsGrid&&!docsGrid.querySelector('a[href="metodologia-prioridade-investigacao.html"]'))docsGrid.insertAdjacentHTML('afterbegin','<a class="docs-link-card featured" href="metodologia-prioridade-investigacao.html">Prioridade por pergunta<small>Classes P1 a P5 e confiança C1 a C5 mantidas separadas.</small></a>');
