let activeIRKey=null,activeIRMetric='pct_source_snapshot_overlap',irMeta=null,selectedIRLayer=null,selectedIRKey=null;
async function ensureIRMeta(){if(irMeta)return irMeta;irMeta=await getJSON('data/independence_redundancy/independence_style_metadata.json');return irMeta;}
function irMetricDef(){return irMeta?.metrics?.[activeIRMetric]||{label:activeIRMetric,unit:'',family:'review'};}
function irMetricMeta(scale){return irMeta?.scales?.[String(scale)]?.[activeIRMetric]||{quantiles:[]};}
function irColor(v,q,fam){if(v===null||v===undefined||Number.isNaN(Number(v)))return 'transparent';const pals={source:['#eef5fb','#d2e6f4','#9bc7e0','#599fc5','#1f6d99'],review:['#fff4e6','#fdd9a5','#f9b76b','#e98934','#b75a13'],spatial:['#f4f1f8','#ded6ea','#baa9cf','#8a72ad','#5d4680'],diversity:['#edf7f5','#cce9e3','#91d2c6','#4da99b','#176f67'],records:['#eef2f6','#ced8e2','#9eb1c3','#687f96','#405568'],count:['#edf6fb','#cde6f2','#9ecae1','#5ba3cf','#2171b5']};const pal=pals[fam]||pals.review;let i=0;for(const x of(q||[]))if(Number(v)>Number(x))i++;return pal[Math.min(i,pal.length-1)];}
function independenceStyle(f,key){const p=f.properties||{},scale=key.replace('ir',''),m=irMetricDef(),meta=irMetricMeta(scale),v=Number(p[activeIRMetric]);const defined=Number.isFinite(v)&&Number(p.n_wells_raw)>0;return{pane:'gridPane',color:'#4b545d',weight:.8,opacity:.9,fillColor:defined?irColor(v,meta.quantiles,m.family):'transparent',fillOpacity:defined?.73:0};}
function clearIRHighlight(){if(selectedIRLayer&&selectedIRKey&&selectedIRLayer.feature){try{selectedIRLayer.setStyle(independenceStyle(selectedIRLayer.feature,selectedIRKey));}catch(e){}}selectedIRLayer=null;selectedIRKey=null;}
function highlightIRCell(layer,key){if(selectedIRLayer&&selectedIRLayer!==layer&&selectedIRKey&&selectedIRLayer.feature){try{selectedIRLayer.setStyle(independenceStyle(selectedIRLayer.feature,selectedIRKey));}catch(e){}}selectedIRLayer=layer;selectedIRKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.8});if(layer?.bringToFront)layer.bringToFront();}
function irNum(v,d=2,s=''){return valid(v)&&Number.isFinite(Number(v))?Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})+s:null;}
function independenceFicha(p){const m=irMetricDef(),suffix=m.unit==='%'?'%':'';return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">Independência e redundância · ${esc(p.scale_km2)} km²</div><div class="well-badges"><span class="well-badge review">CENÁRIOS DE SENSIBILIDADE</span><span class="well-badge unknown">SEM n EFETIVO · SEM SCORE PIH</span></div></div><section class="ficha-section"><h4>Métrica selecionada</h4><div class="ficha-grid">${frow(m.label,irNum(p[activeIRMetric],2,suffix),'derived')}${frow('Poços canônicos na célula',p.n_wells_raw,'derived')}</div></section><section class="ficha-section"><h4>Repetição de fonte</h4><div class="ficha-grid">${frow('Poços presentes nos dois snapshots',p.source_snapshot_overlap_n,'derived')}${frow('Sobreposição entre snapshots',irNum(p.pct_source_snapshot_overlap,1,'%'),'derived')}${frow('Pares centrais comparáveis',p.source_core_pairs_comparable_n,'derived')}${frow('Pares coincidentes',p.source_core_pairs_matching_n,'derived')}${frow('Coincidência documental',irNum(p.source_core_match_pct,1,'%'),'derived')}</div><div class="ficha-note">O mesmo well_id em duas versões da fonte não é contado como duas observações independentes.</div></section><section class="ficha-section"><h4>Co-localização e candidatos a duplicação</h4><div class="ficha-grid">${frow('Locais por coordenada idêntica',p.coordinate_sites_n,'derived')}${frow('Compressão por coordenada',irNum(p.coordinate_compression_pct,1,'%'),'derived')}${frow('Poços candidatos a duplicação',p.duplicate_candidate_wells_n,'derived')}${frow('Candidatos HIGH',p.high_duplicate_candidate_wells_n,'derived')}${frow('Cenário máximo · grupos',p.review_all_clusters_n,'derived')}${frow('Cenário máximo · redução',irNum(p.review_all_reduction_pct,1,'%'),'derived')}</div><div class="ficha-note">Esses cenários não removem IDs. Coordenada idêntica ou par candidato não prova que dois registros representem o mesmo poço físico.</div></section><section class="ficha-section"><h4>Concentração espacial</h4><div class="ficha-grid">${frow('Vizinho &lt;100 m',irNum(p.nn_lt_100m_pct,1,'%'),'derived')}${frow('Vizinho &lt;500 m',irNum(p.nn_lt_500m_pct,1,'%'),'derived')}${frow('Vizinho &lt;1 km',irNum(p.nn_lt_1000m_pct,1,'%'),'derived')}${frow('Distância mediana ao vizinho',irNum(p.nearest_neighbor_median_m,1,' m'),'derived')}</div><div class="ficha-note">Proximidade espacial não demonstra redundância hidráulica, vertical ou temporal.</div></section><section class="ficha-section"><h4>Diversidade documental</h4><div class="ficha-grid">${frow('Domínios documentais · mediana',irNum(p.documentary_domains_median,1,''),'derived')}${frow('Sem domínio adicional',irNum(p.zero_domains_pct,1,'%'),'derived')}${frow('Com 4–5 domínios',irNum(p.fourplus_domains_pct,1,'%'),'derived')}${frow('Domínios datados · mediana',irNum(p.dated_domains_median,1,''),'derived')}</div><div class="ficha-note">Diversidade documental alta não equivale a independência estatística nem qualidade certificada.</div></section><section class="ficha-section"><h4>Estrutura de registros</h4><div class="ficha-grid">${frow('Registros de ensaio',p.pumping_test_records_n,'derived')}${frow('Registros de amostra química',p.chem_sample_records_n,'derived')}${frow('Resultados químicos',p.chem_result_records_n,'derived')}${frow('Registros de parâmetros hidráulicos',p.hydraulic_parameter_records_n,'derived')}${frow('Amostras químicas por poço',irNum(p.chem_sample_records_per_well,2,''),'derived')}${frow('Parâmetros hidráulicos por poço',irNum(p.hydraulic_parameter_records_per_well,2,''),'derived')}</div><div class="ficha-note">Analitos diferentes e parâmetros de naturezas diferentes não são réplicas equivalentes.</div><p><a href="guia-resultados.html#independencia" target="_blank">Como ler independência</a> · <a href="metodologia-independencia-redundancia.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function openIndependenceFeature(p,layer,key){highlightIRCell(layer,key);lastSelection={key,p,independence:true};info.innerHTML=independenceFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · independência e redundância`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
async function showIndependence(){const scale=document.getElementById('irScale')?.value||'250',metric=document.getElementById('irMetric')?.value||'pct_source_snapshot_overlap',key='ir'+scale;await ensureIRMeta();activeIRMetric=metric;clearIRHighlight();if(activeVTKey)hideVerticalTemporal();if(activeStratifiedKey)hideStratified();if(activeScaleStudyKey)hideScaleStudy();if(activeSpatialKey)hideSpatialStructure();if(activeGridEvidenceKey)hideGridEvidence();if(activeIRKey&&activeIRKey!==key&&layers[activeIRKey])map.removeLayer(layers[activeIRKey]);activeIRKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>independenceStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='INDEPENDÊNCIA E REDUNDÂNCIA · clique em uma célula';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);updateLegend();}
function hideIndependence(){if(activeIRKey&&layers[activeIRKey]&&map.hasLayer(layers[activeIRKey]))map.removeLayer(layers[activeIRKey]);clearIRHighlight();activeIRKey=null;updateLegend();}

let activeVTKey=null,activeVTMetric='T04_any_dated_pct_of_wells',vtMeta=null,selectedVTLayer=null,selectedVTKey=null;
async function ensureVTMeta(){if(vtMeta)return vtMeta;vtMeta=await getJSON('data/vertical_temporal/vertical_temporal_style_metadata.json');return vtMeta;}
function vtMetricMeta(scale){return vtMeta?.scales?.[String(scale)]?.[activeVTMetric]||{quantiles:[]};}
function vtMetricDef(){return vtMeta?.metrics?.[activeVTMetric]||{label:activeVTMetric,unit:'',family:'vertical'};}
function vtColor(v,q,fam){if(v===null||v===undefined||Number.isNaN(Number(v)))return 'transparent';const pals={vertical:['#e5f5f9','#b2e2e2','#66c2a4','#2ca25f','#006d5b'],temporal:['#f2f0f7','#dadaeb','#bcbddc','#9e9ac8','#6a51a3'],age:['#f2f0f7','#cbc9e2','#9e9ac8','#756bb1','#54278f']};const pal=pals[fam]||pals.vertical;let i=0;for(const x of (q||[]))if(Number(v)>Number(x))i++;return pal[Math.min(i,pal.length-1)];}
function verticalTemporalGridStyle(f,key){const p=f.properties||{},scale=key.replace('vt',''),m=vtMetricDef(),meta=vtMetricMeta(scale),v=Number(p[activeVTMetric]);const defined=Number.isFinite(v)&&(p.vt_n_wells>0||activeVTMetric==='T06_rimas_registered_n');return{pane:'gridPane',color:'#4b545d',weight:.8,opacity:.9,fillColor:defined?vtColor(v,meta.quantiles,m.family):'transparent',fillOpacity:defined?.72:0};}
function clearVTHighlight(){if(selectedVTLayer&&selectedVTKey&&selectedVTLayer.feature){try{selectedVTLayer.setStyle(verticalTemporalGridStyle(selectedVTLayer.feature,selectedVTKey));}catch(e){}}selectedVTLayer=null;selectedVTKey=null;}
function highlightVTCell(layer,key){if(selectedVTLayer&&selectedVTLayer!==layer&&selectedVTKey&&selectedVTLayer.feature){try{selectedVTLayer.setStyle(verticalTemporalGridStyle(selectedVTLayer.feature,selectedVTKey));}catch(e){}}selectedVTLayer=layer;selectedVTKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.8});if(layer?.bringToFront)layer.bringToFront();}
function vtNum(v,d=2,s=''){return valid(v)&&Number.isFinite(Number(v))?Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})+s:null;}
function verticalTemporalFicha(p){const m=vtMetricDef();const suffix=m.unit==='%'?'%':m.unit==='anos'?' anos':'';return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">Documentação vertical e temporal · ${esc(p.scale_km2)} km²</div><div class="well-badges"><span class="well-badge review">MÉTRICA DOCUMENTAL</span><span class="well-badge unknown">SEM SCORE PIH</span></div></div><section class="ficha-section"><h4>Métrica selecionada</h4><div class="ficha-grid">${frow(m.label,vtNum(p[activeVTMetric],2,suffix),'derived')}${frow('Poços na célula',p.vt_n_wells,'derived')}</div></section><section class="ficha-section"><h4>Documentação vertical</h4><div class="ficha-grid">${frow('Profundidade positiva',p.V01_depth_positive_n,'derived')}${frow('Formação documentada',p.V02_formation_n,'derived')}${frow('Tipo de penetração',p.V03_penetration_n,'derived')}${frow('Condição hidráulica',p.V04_hydraulic_condition_n,'derived')}${frow('Tipo de captação',p.V05_capture_type_n,'derived')}${frow('Topo e base brutos',p.V06_top_base_raw_n,'derived')}${frow('Diâmetro',p.V07_diameter_n,'derived')}${frow('Intervalo de filtro demonstrado',p.V08_screen_interval_n,'derived')}</div><div class="ficha-note">Profundidade não demonstra intervalo captado. Topo e base brutos não são reinterpretados como tela ou filtro. O intervalo captado permanece UNKNOWN.</div></section><section class="ficha-section"><h4>Documentação temporal</h4><div class="ficha-grid">${frow('Ensaios datados',p.T01_test_dated_n,'derived')}${frow('Química datada',p.T02_chemistry_dated_n,'derived')}${frow('Medições de nível datadas',p.T03_level_dated_n,'derived')}${frow('Poços com alguma evidência datada',p.T04_any_dated_n,'derived')}${frow('Múltiplos domínios datados',p.T05_multi_domain_dated_n,'derived')}${frow('Cadastros RIMAS',p.T06_rimas_registered_n,'derived')}${frow('Séries temporais demonstradas',p.T07_series_demonstrated_n,'derived')}${frow('Idade mediana da última evidência',vtNum(p.latest_evidence_age_median_years,2,' anos'),'derived')}${frow('Anos distintos no acervo da célula',p.dated_distinct_years_n,'derived')}${frow('Amplitude das datas do acervo',vtNum(p.dated_dataset_span_years,2,' anos'),'derived')}</div><div class="ficha-note">Amplitude de datas entre poços não é uma série temporal. Cadastro RIMAS não prova que a série correspondente tenha sido adquirida.</div></section><section class="ficha-section"><h4>UNKNOWN preservado</h4><div class="ficha-grid">${frow('Intervalo de captação',p.capture_interval_status,'derived')}${frow('Série temporal',p.time_series_status,'derived')}</div><p><a href="guia-resultados.html#vertical" target="_blank">Como ler vertical e tempo</a> · <a href="metodologia-vertical-temporal.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function openVerticalTemporalFeature(p,layer,key){highlightVTCell(layer,key);lastSelection={key,p,verticalTemporal:true};info.innerHTML=verticalTemporalFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · vertical e temporal`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
async function showVerticalTemporal(){const scale=document.getElementById('vtScale')?.value||'250',metric=document.getElementById('vtMetric')?.value||'T04_any_dated_pct_of_wells',key='vt'+scale;await ensureVTMeta();activeVTMetric=metric;clearVTHighlight();if(activeStratifiedKey)hideStratified();if(activeScaleStudyKey)hideScaleStudy();if(activeSpatialKey)hideSpatialStructure();if(activeGridEvidenceKey)hideGridEvidence();if(activeVTKey&&activeVTKey!==key&&layers[activeVTKey])map.removeLayer(layers[activeVTKey]);activeVTKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>verticalTemporalGridStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='VERTICAL E TEMPORAL ATIVO · clique em uma célula';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);updateLegend();}
function hideVerticalTemporal(){clearVTHighlight();if(activeVTKey&&layers[activeVTKey]&&map.hasLayer(layers[activeVTKey]))map.removeLayer(layers[activeVTKey]);activeVTKey=null;updateLegend();}

let activeSpatialKey=null,activeSpatialMetric='gap_p90',activeSpatialEvidence='E01',spatialStyleMeta=null,selectedSpatialLayer=null,selectedSpatialKey=null;
async function ensureSpatialMeta(){if(spatialStyleMeta)return spatialStyleMeta;spatialStyleMeta=await getJSON('data/spatial_structure/spatial_structure_style_metadata.json');return spatialStyleMeta;}
function spatialValue(p){const metric=activeSpatialMetric||'gap_p90',code=activeSpatialEvidence||'E01';if(metric==='gap_p90')return Number(p['gap_'+code+'_p90_km']);if(metric==='gap_max')return Number(p['gap_'+code+'_max_km']);return Number(p[metric]);}
function spatialMetricMeta(scale){const metric=activeSpatialMetric||'gap_p90',code=activeSpatialEvidence||'E01';const s=spatialStyleMeta?.scales?.[scale]?.[metric];return metric.startsWith('gap_')?s?.[code]:s;}
function spatialStructureColor(v,q){if(v===null||v===undefined||Number.isNaN(Number(v)))return 'transparent';const pal=['#edf6fb','#cde6f2','#9ecae1','#5ba3cf','#2171b5','#084a7a'];const qs=q||[];let i=0;for(let k=0;k<qs.length;k++)if(Number(v)>Number(qs[k]))i=k+1;return pal[Math.min(i,pal.length-1)];}
function spatialStructureStyle(f,key){const p=f.properties||{},scale=key.replace('se',''),v=spatialValue(p),meta=spatialMetricMeta(scale);const defined=v!==null&&v!==undefined&&!Number.isNaN(Number(v));return{pane:'gridPane',color:'#4b545d',weight:.8,opacity:.88,fillColor:defined?spatialStructureColor(v,meta?.quantiles||[]):'transparent',fillOpacity:defined?.72:0};}
function clearSpatialHighlight(){if(selectedSpatialLayer&&selectedSpatialKey&&selectedSpatialLayer.feature){try{selectedSpatialLayer.setStyle(spatialStructureStyle(selectedSpatialLayer.feature,selectedSpatialKey));}catch(e){}}selectedSpatialLayer=null;selectedSpatialKey=null;}
function highlightSpatialCell(layer,key){if(selectedSpatialLayer&&selectedSpatialLayer!==layer&&selectedSpatialKey&&selectedSpatialLayer.feature){try{selectedSpatialLayer.setStyle(spatialStructureStyle(selectedSpatialLayer.feature,selectedSpatialKey));}catch(e){}}selectedSpatialLayer=layer;selectedSpatialKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.78});if(layer?.bringToFront)layer.bringToFront();}
function spatialNum(v,dec=2,suffix=''){return valid(v)&&!Number.isNaN(Number(v))?Number(v).toFixed(dec)+suffix:'UNKNOWN';}
function spatialStructureFicha(p){const code=activeSpatialEvidence||'E01',metric=activeSpatialMetric||'gap_p90';const meta=spatialStyleMeta?.metrics?.[metric]||{label:metric,unit:''};const sel=spatialValue(p);return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.pih_cell_id||'Hexágono')}</div><div class="well-sub">Estrutura espacial · ${esc(p.scale_km2)} km² · sem score PIH</div><div class="well-badges"><span class="well-badge review">MÉTRICA DESCRITIVA</span><span class="well-badge unknown">PREDIÇÃO NÃO UTILIZADA</span></div></div><section class="ficha-section"><h4>Métrica selecionada</h4><div class="ficha-grid">${frow(meta.label,Number.isNaN(sel)?null:spatialNum(sel,2,meta.unit==='km'?' km':meta.unit==='%'?'%':''),'derived')}${frow('Evidência de referência',code+' · '+(evidenceInfo[code.toLowerCase()]?.name||code),'derived')}${frow('Poços E01 na célula',p.n_E01,'derived')}${frow('Área efetiva em MS',spatialNum(p.area_effective_km2,2,' km²'),'derived')}</div></section><section class="ficha-section"><h4>Distribuição E01</h4><div class="ficha-grid">${frow('Vizinho global mediano',spatialNum(p.nn_global_median_km,2,' km'),'derived')}${frow('Vizinho global P90',spatialNum(p.nn_global_p90_km,2,' km'),'derived')}${frow('Vizinho interno mediano',spatialNum(p.nn_within_median_km,2,' km'),'derived')}${frow('Ocupação suporte 2,5 km',spatialNum(p.support_area_2p5km_pct,2,'%'),'derived')}${frow('Ocupação suporte 5 km',spatialNum(p.support_area_5km_pct,2,'%'),'derived')}${frow('Ocupação suporte 10 km',spatialNum(p.support_area_10km_pct,2,'%'),'derived')}${frow('Redundância proxy 5 km',spatialNum(p.redundancy_proxy_5km,3,''),'derived')}${frow('Entropia normalizada 5 km',spatialNum(p.entropy_norm_5km,3,''),'derived')}${frow('Dominância 5 km',spatialNum(p.dominance_5km_pct,2,'%'),'derived')}${frow('Envoltória convexa / célula',spatialNum(p.convex_hull_area_ratio,3,''),'derived')}</div></section><section class="ficha-section"><h4>Vazio espacial até ${code}</h4><div class="ficha-grid">${frow('Distância mediana',spatialNum(p['gap_'+code+'_median_km'],2,' km'),'derived')}${frow('Distância P90',spatialNum(p['gap_'+code+'_p90_km'],2,' km'),'derived')}${frow('Distância máxima',spatialNum(p['gap_'+code+'_max_km'],2,' km'),'derived')}${frow('Pontos fixos de suporte',p.gap_support_points_n,'derived')}${frow('Contingência de suporte',p.gap_support_fallback,'derived')}</div></section><section class="ficha-section"><h4>Leitura obrigatória</h4><div class="ficha-note">Distância à evidência não é distância à água subterrânea. Ocupação interna não é porcentagem de conhecimento hidrogeológico. Redundância e entropia são descritores geométricos e não medem independência hidrogeológica completa.</div><p><a href="guia-resultados.html#estrutura" target="_blank">Como ler estas métricas</a> · <a href="metodologia-estrutura-espacial.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function openSpatialStructureFeature(p,layer,key){highlightSpatialCell(layer,key);lastSelection={key,p,spatialStructure:true};info.innerHTML=spatialStructureFicha(p);openRight();statusEl.textContent=`${p.pih_cell_id||'Hexágono'} · estrutura espacial aberta`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
async function showSpatialStructure(){if(activeStratifiedKey)hideStratified();if(activeScaleStudyKey)hideScaleStudy();const scale=document.getElementById('spatialScale')?.value||'250',metric=document.getElementById('spatialMetric')?.value||'gap_p90',code=document.getElementById('spatialEvidence')?.value||'E01',key='se'+scale;await ensureSpatialMeta();activeSpatialMetric=metric;activeSpatialEvidence=code;clearSpatialHighlight();if(activeGridEvidenceKey)hideGridEvidence();if(activeSpatialKey&&activeSpatialKey!==key&&layers[activeSpatialKey])map.removeLayer(layers[activeSpatialKey]);activeSpatialKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>spatialStructureStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='ESTRUTURA ESPACIAL ATIVA · clique em um hexágono para abrir a ficha';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2400);updateSpatialEvidenceControl();updateLegend();}
function hideSpatialStructure(){clearSpatialHighlight();if(activeSpatialKey&&layers[activeSpatialKey]&&map.hasLayer(layers[activeSpatialKey]))map.removeLayer(layers[activeSpatialKey]);activeSpatialKey=null;updateLegend();}
function updateSpatialEvidenceControl(){const m=document.getElementById('spatialMetric')?.value||'gap_p90',lab=document.getElementById('spatialEvidenceLabel');if(lab)lab.style.display=m.startsWith('gap_')?'block':'none';}

let activeGridEvidenceKey=null, activeGridEvidenceCode='E01', gridEvidenceStyleMeta=null;
async function ensureGridEvidenceMeta(){if(gridEvidenceStyleMeta)return gridEvidenceStyleMeta;gridEvidenceStyleMeta=await getJSON('data/grid_evidence/grid_evidence_style_metadata.json');return gridEvidenceStyleMeta;}
function gridEvidenceColor(code,count,breaks){if(!count||count<=0)return 'transparent';const palette=code==='E12'?['#fee8c8','#fdbb84','#fc8d59','#d7301f','#8c2d04']:['#dbeef7','#a6cee3','#6baed6','#3182bd','#08519c'];let idx=0;for(let i=0;i<breaks.length;i++)if(count>breaks[i])idx=i+1;return palette[Math.min(idx,palette.length-1)];}
function gridEvidenceStyle(f,key){const code=activeGridEvidenceCode||'E01';const n=Number(f.properties?.['n_'+code]||0);const meta=gridEvidenceStyleMeta?.[key.replace('ge','')]?.[code]||{count_breaks:[]};return {pane:'gridPane',color:'#4b545d',weight:.8,opacity:.85,fillColor:gridEvidenceColor(code,n,meta.count_breaks||[]),fillOpacity:n>0?.68:0};}
function gridEvidenceFicha(p){const code=activeGridEvidenceCode||'E01';let items='';for(let i=1;i<=12;i++){const c='E'+String(i).padStart(2,'0'),n=Number(p['n_'+c]||0),pc=i===1?(n?100:null):p['pct_'+c+'_of_E01'];items+=`<div class="grid-cell-item"><b>${c} · ${esc(evidenceInfo[c.toLowerCase()]?.name||c)}</b><strong>${n.toLocaleString('pt-BR')}</strong><div>${pc===null||pc===undefined||Number.isNaN(Number(pc))?'<span class="grid-unknown">UNKNOWN</span>':Number(pc).toFixed(1)+'% dos poços E01'}</div><small>${esc(p['state_'+c]||'')}</small></div>`;}return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.pih_cell_id)}</div><div class="well-sub">Malha candidata ${esc(p.area_nominal_km2)} km² · área efetiva em MS ${fmt(p.area_efetiva_ms_km2,2)} km²</div><div class="well-badges"><span class="well-badge unknown">SEM SCORE PIH</span><span class="well-badge review">Camada ativa ${esc(code)}</span></div></div><section class="ficha-section"><h4>Matriz de evidência da célula</h4><div class="grid-cell-matrix">${items}</div><div class="ficha-note">Percentuais usam E01 da própria célula como denominador e medem cobertura cadastral do atributo. Não medem conhecimento hidrogeológico total.</div></section><section class="ficha-section"><h4>Estatísticas descritivas disponíveis</h4><div class="ficha-grid">${frow('Profundidade mediana',p.E02_depth_median_m,'derived',' m')}${frow('Profundidade P10',p.E02_depth_p10_m,'derived',' m')}${frow('Profundidade P90',p.E02_depth_p90_m,'derived',' m')}${frow('Aquíferos nominais distintos',p.E03_aquifer_n_unique,'derived')}${frow('Zeros NE em revisão',p.E04_zero_review_count,'derived')}${frow('Zeros ND em revisão',p.E05_zero_review_count,'derived')}${frow('Mediana campos hidroquímicos disponíveis',p.E10_available_fields_median,'derived')}${frow('Antiguidade mediana E11',p.E11_age_median_years,'derived',' anos')}</div></section><section class="ficha-section"><h4>Leitura obrigatória</h4><div class="ficha-note">Hexágono sem E01 é UNKNOWN no conjunto auditado e não significa ausência de água subterrânea. Hexágono com E01 mas sem outra evidência significa somente ausência desse atributo nos poços auditados desta célula.</div><p><a href="guia-resultados.html#evidencias" target="_blank">Como ler estes resultados</a> · <a href="metodologia-malhas-evidencia.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function clearGridHighlight(){if(selectedGridLayer&&selectedGridKey&&selectedGridLayer.feature){try{selectedGridLayer.setStyle(gridEvidenceStyle(selectedGridLayer.feature,selectedGridKey));}catch(e){}}selectedGridLayer=null;selectedGridKey=null;}
function highlightGridCell(layer,key){if(selectedGridLayer&&selectedGridLayer!==layer&&selectedGridKey&&selectedGridLayer.feature){try{selectedGridLayer.setStyle(gridEvidenceStyle(selectedGridLayer.feature,selectedGridKey));}catch(e){}}selectedGridLayer=layer;selectedGridKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:Number(layer.feature?.properties?.['n_'+(activeGridEvidenceCode||'E01')]||0)>0?.74:.08});if(layer?.bringToFront)layer.bringToFront();}
function openGridEvidenceFeature(p,layer,key){highlightGridCell(layer,key);lastSelection={key,p,gridEvidence:true};info.innerHTML=gridEvidenceFicha(p);openRight();statusEl.textContent=`${p.pih_cell_id||'Hexágono'} selecionado · ficha da malha aberta`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
function openGridCellAt(latlng){if(!activeGridEvidenceKey)return false;const group=layers[activeGridEvidenceKey];if(!group||!map.hasLayer(group))return false;const pt=map.latLngToLayerPoint(latlng);let found=null;group.eachLayer(l=>{if(found||!l.feature)return;try{if(typeof l._containsPoint==='function'&&l._containsPoint(pt))found=l;}catch(e){}if(!found&&l.getBounds?.().contains(latlng))found=l;});if(!found)return false;openGridEvidenceFeature(found.feature.properties||{},found,activeGridEvidenceKey);return true;}

async function showGridEvidence(){if(activeStratifiedKey)hideStratified();if(activeScaleStudyKey)hideScaleStudy();if(activeSpatialKey)hideSpatialStructure();const scale=document.getElementById('gridEvidenceScale')?.value||'250',code=document.getElementById('gridEvidenceCode')?.value||'E01';const key='ge'+scale;await ensureGridEvidenceMeta();clearGridHighlight();activeGridEvidenceCode=code;if(activeGridEvidenceKey&&activeGridEvidenceKey!==key&&layers[activeGridEvidenceKey])map.removeLayer(layers[activeGridEvidenceKey]);activeGridEvidenceKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>gridEvidenceStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='MALHA ATIVA · clique em qualquer hexágono para abrir a ficha completa';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2600);updateLegend();}
function hideGridEvidence(){clearGridHighlight();if(activeGridEvidenceKey&&layers[activeGridEvidenceKey]&&map.hasLayer(layers[activeGridEvidenceKey]))map.removeLayer(layers[activeGridEvidenceKey]);activeGridEvidenceKey=null;updateLegend();}


let activeStratifiedKey=null,activeStratifiedMetric='hydro_dominant_unit_pct',selectedStratifiedLayer=null,selectedStratifiedKey=null;
function stratifiedValue(p){const m=activeStratifiedMetric;const v=p?.[m];if(typeof v==='boolean')return v?1:0;if(v===null||v===undefined||v==='')return null;const n=Number(v);return Number.isFinite(n)?n:v;}
function stratifiedMetricLabel(m){const labels={hydro_dominant_unit_pct:'Pureza da unidade dominante',units_n:'Número de unidades na célula',dominant_domain_pct:'Pureza do domínio dominante',domains_n:'Número de domínios na célula',E01_dominant_unit_n:'E01 na unidade dominante',E07_dominant_unit_n:'E07 na unidade dominante',E09_dominant_unit_n:'E09 na unidade dominante',E10_dominant_unit_n:'E10 na unidade dominante',E01_dominant_unit_masked:'Mascaramento E01 pela unidade dominante',E07_dominant_unit_masked:'Mascaramento E07 pela unidade dominante',E09_dominant_unit_masked:'Mascaramento E09 pela unidade dominante',E10_dominant_unit_masked:'Mascaramento E10 pela unidade dominante',E01_dominant_domain_masked:'Mascaramento E01 pelo domínio dominante',E07_dominant_domain_masked:'Mascaramento E07 pelo domínio dominante',E09_dominant_domain_masked:'Mascaramento E09 pelo domínio dominante',E10_dominant_domain_masked:'Mascaramento E10 pelo domínio dominante'};return labels[m]||m;}
function stratifiedStyle(f,key){const p=f.properties||{},m=activeStratifiedMetric,v=stratifiedValue(p);let fill='transparent',op=0;if(m.endsWith('_masked')){if(v===1){fill='#e67e22';op=.78;}}else if(m==='hydro_dominant_unit_pct'||m==='dominant_domain_pct'){if(Number.isFinite(Number(v))){const x=Number(v);fill=x>=95?'#0b4f6c':x>=85?'#247ba0':x>=70?'#70b7d6':x>=50?'#b8dcec':'#e8f4f8';op=.72;}}else if(m==='units_n'||m==='domains_n'){if(Number.isFinite(Number(v))&&Number(v)>0){const x=Number(v);fill=x<=1?'#eeeaf5':x===2?'#d4c5e2':x===3?'#aa8cc5':'#76519c';op=.72;}}else{if(Number.isFinite(Number(v))&&Number(v)>0){const x=Number(v);fill=x===1?'#c8e8e3':x<=3?'#7fcac1':x<=10?'#2f9e91':'#096b63';op=.74;}}return{pane:'gridPane',color:'#4b545d',weight:.85,opacity:.9,fillColor:fill,fillOpacity:op};}
function clearStratifiedHighlight(){if(selectedStratifiedLayer&&selectedStratifiedKey&&selectedStratifiedLayer.feature){try{selectedStratifiedLayer.setStyle(stratifiedStyle(selectedStratifiedLayer.feature,selectedStratifiedKey));}catch(e){}}selectedStratifiedLayer=null;selectedStratifiedKey=null;}
function highlightStratifiedCell(layer,key){if(selectedStratifiedLayer&&selectedStratifiedLayer!==layer&&selectedStratifiedKey&&selectedStratifiedLayer.feature){try{selectedStratifiedLayer.setStyle(stratifiedStyle(selectedStratifiedLayer.feature,selectedStratifiedKey));}catch(e){}}selectedStratifiedLayer=layer;selectedStratifiedKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.82});if(layer?.bringToFront)layer.bringToFront();}
function stratBool(v){return v===true||String(v).toLowerCase()==='true'?'SIM':'NÃO';}
function stratifiedFicha(p){const m=activeStratifiedMetric;let mv=stratifiedValue(p);if(m.includes('_pct')&&Number.isFinite(Number(mv)))mv=Number(mv).toFixed(1)+'%';return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula')}</div><div class="well-sub">Estratificação hidrogeológica · ${esc(p.scale_km2)} km² · origem O00</div><div class="well-badges"><span class="well-badge review">INTERSEÇÃO VETORIAL EXATA</span><span class="well-badge unknown">SEM SCORE PIH</span></div></div><section class="ficha-section"><h4>Métrica selecionada</h4><div class="ficha-grid">${frow(stratifiedMetricLabel(m),mv,'derived')}${frow('Área efetiva em MS',scaleStudyNum(p.area_effective_km2,2,' km²'),'derived')}</div></section><section class="ficha-section"><h4>Composição do hexágono</h4><div class="ficha-grid">${frow('Unidade dominante',p.dominant_unit,'derived')}${frow('Fração da unidade dominante',scaleStudyNum(p.dominant_unit_pct,1,'%'),'derived')}${frow('Número de unidades',p.units_n,'derived')}${frow('Domínio dominante',p.dominant_domain,'derived')}${frow('Fração do domínio dominante',scaleStudyNum(p.dominant_domain_pct,1,'%'),'derived')}${frow('Número de domínios',p.domains_n,'derived')}</div></section><section class="ficha-section"><h4>Evidência total e no estrato dominante</h4><div class="grid-cell-matrix">${['E01','E07','E09','E10'].map(c=>`<div class="grid-cell-item"><b>${c}</b><strong>${Number(p[c+'_total']||0).toLocaleString('pt-BR')} total</strong><div>${Number(p[c+'_dominant_unit_n']||0)} na unidade dominante</div><div>${Number(p[c+'_dominant_domain_n']||0)} no domínio dominante</div><small>Mascaramento unidade ${stratBool(p[c+'_dominant_unit_masked'])} · domínio ${stratBool(p[c+'_dominant_domain_masked'])}</small></div>`).join('')}</div></section><section class="ficha-section"><h4>Leitura obrigatória</h4><div class="ficha-note">Unidade dominante não significa unidade única. Mascaramento indica que a célula contém a evidência selecionada, mas não há evidência atribuída ao estrato dominante. Isto mede um efeito da agregação espacial e não um erro geológico.</div><p><a href="guia-resultados.html#estratos" target="_blank">Como ler mistura e mascaramento</a> · <a href="metodologia-estratificacao-hidrogeologica.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function openStratifiedFeature(p,layer,key){highlightStratifiedCell(layer,key);lastSelection={key,p,stratified:true};info.innerHTML=stratifiedFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · estratificação aberta`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1800);}
async function showStratified(){const scale=document.getElementById('stratScale')?.value||'250',metric=document.getElementById('stratMetric')?.value||'hydro_dominant_unit_pct',key='st'+scale;activeStratifiedMetric=metric;clearStratifiedHighlight();if(activeScaleStudyKey)hideScaleStudy();if(activeSpatialKey)hideSpatialStructure();if(activeGridEvidenceKey)hideGridEvidence();if(activeStratifiedKey&&activeStratifiedKey!==key&&layers[activeStratifiedKey])map.removeLayer(layers[activeStratifiedKey]);activeStratifiedKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>stratifiedStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='ESTRATIFICAÇÃO ATIVA · clique em um hexágono para abrir a ficha';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2400);updateLegend();}
