let activeScaleStudyKey=null,activeScaleStudyMetric='n_E01',scaleStudyMeta=null,selectedScaleStudyLayer=null,selectedScaleStudyKey=null;
async function ensureScaleStudyMeta(){if(scaleStudyMeta)return scaleStudyMeta;scaleStudyMeta=await getJSON('data/scale_study/scale_candidate_style_metadata.json');return scaleStudyMeta;}
function scaleStudyValue(p){return Number(p?.[activeScaleStudyMetric]);}
function scaleStudyMetricMeta(scale){return scaleStudyMeta?.scales?.[String(scale)]?.[activeScaleStudyMetric]||{quantiles:[]};}
function scaleStudyColor(v,q,palette){if(v===null||v===undefined||Number.isNaN(Number(v)))return 'transparent';const x=Number(v),qq=q||[];let i=0;while(i<qq.length&&x>Number(qq[i]))i++;return palette[Math.min(i,palette.length-1)];}
function scaleStudyStyle(f,key){const p=f.properties||{},scale=key.replace('sc',''),v=scaleStudyValue(p),m=scaleStudyMeta?.metrics?.[activeScaleStudyMetric]||{},meta=scaleStudyMetricMeta(scale),pal=m.palette==='purple'?['#f2eef7','#dadaeb','#bcbddc','#9e9ac8','#756bb1']:['#edf6fb','#cde6f2','#9ecae1','#5ba3cf','#2171b5'];const defined=Number.isFinite(v);return{pane:'gridPane',color:'#4b545d',weight:.8,opacity:.9,fillColor:defined?scaleStudyColor(v,meta.quantiles,pal):'transparent',fillOpacity:defined?.7:0};}
function clearScaleStudyHighlight(){if(selectedScaleStudyLayer&&selectedScaleStudyKey&&selectedScaleStudyLayer.feature){try{selectedScaleStudyLayer.setStyle(scaleStudyStyle(selectedScaleStudyLayer.feature,selectedScaleStudyKey));}catch(e){}}selectedScaleStudyLayer=null;selectedScaleStudyKey=null;}
function highlightScaleStudyCell(layer,key){if(selectedScaleStudyLayer&&selectedScaleStudyLayer!==layer&&selectedScaleStudyKey&&selectedScaleStudyLayer.feature){try{selectedScaleStudyLayer.setStyle(scaleStudyStyle(selectedScaleStudyLayer.feature,selectedScaleStudyKey));}catch(e){}}selectedScaleStudyLayer=layer;selectedScaleStudyKey=key;if(layer?.setStyle)layer.setStyle({color:'#082f4f',weight:3,opacity:1,fillOpacity:.78});if(layer?.bringToFront)layer.bringToFront();}
function scaleStudyNum(v,d=2,s=''){return valid(v)&&Number.isFinite(Number(v))?Number(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d})+s:null;}
function scaleStudyFicha(p){const metric=scaleStudyMeta?.metrics?.[activeScaleStudyMetric]||{label:activeScaleStudyMetric,unit:''};return `<div class="well-ficha"><div class="well-hero"><div class="well-id">${esc(p.cell_id||'Célula sintética')}</div><div class="well-sub">Estudo de escala · ${esc(p.scale_km2)} km² · origem O00</div><div class="well-badges"><span class="well-badge review">MALHA SINTÉTICA COMPARATIVA</span><span class="well-badge unknown">SEM SCORE PIH</span></div></div><section class="ficha-section"><h4>Métrica selecionada</h4><div class="ficha-grid">${frow(metric.label,scaleStudyNum(p[activeScaleStudyMetric],2,metric.unit==='km'?' km':metric.unit==='%'?'%':''),'derived')}${frow('Área efetiva em MS',scaleStudyNum(p.area_effective_km2,2,' km²'),'derived')}${frow('Percentual da área nominal',scaleStudyNum(p.area_effective_pct_nominal,1,'%'),'derived')}</div></section><section class="ficha-section"><h4>Evidência observada</h4><div class="ficha-grid">${frow('E01 · poços canônicos',p.n_E01,'derived')}${frow('E07 · ensaios cadastrados',p.n_E07,'derived')}${frow('E09 · transmissividade informada',p.n_E09,'derived')}${frow('E10 · hidroquímica parcial',p.n_E10,'derived')}</div></section><section class="ficha-section"><h4>Vazios espaciais descritivos</h4><div class="ficha-grid">${frow('P90 até E01',scaleStudyNum(p.gap_E01_p90_km,2,' km'),'derived')}${frow('P90 até E07',scaleStudyNum(p.gap_E07_p90_km,2,' km'),'derived')}${frow('P90 até E09',scaleStudyNum(p.gap_E09_p90_km,2,' km'),'derived')}${frow('P90 até E10',scaleStudyNum(p.gap_E10_p90_km,2,' km'),'derived')}</div></section><section class="ficha-section"><h4>Heterogeneidade hidrogeológica no suporte fixo de 5 km</h4><div class="ficha-grid">${frow('Pontos de suporte',p.hydro_support_points_n,'derived')}${frow('Unidades distintas',p.hydro_support_units_n,'derived')}${frow('Dominância da unidade principal',scaleStudyNum(p.hydro_support_dominant_pct,1,'%'),'derived')}${frow('Entropia normalizada',scaleStudyNum(p.hydro_support_entropy,3,''),'derived')}${frow('Classes hidrogeológicas',p.hydro_support_classes_n,'derived')}</div><div class="ficha-note">Esta heterogeneidade é uma aproximação baseada nos pontos fixos de suporte de 5 km classificados pelo mapa SGB 2024. Não é uma fração de área exata.</div></section><section class="ficha-section"><h4>Leitura obrigatória</h4><div class="ficha-note">A malha O00 é sintética e serve apenas para comparar resoluções de 100, 150, 250, 500 e 1000 km² sob a mesma geometria de geração. Célula vazia não significa ausência de água. Maior ocupação de células não significa maior conhecimento.</div><p><a href="guia-resultados.html#escalas" target="_blank">Como comparar escalas</a> · <a href="metodologia-escalas-candidatas.html" target="_blank">Metodologia completa</a></p></section></div>`;}
function openScaleStudyFeature(p,layer,key){highlightScaleStudyCell(layer,key);lastSelection={key,p,scaleStudy:true};info.innerHTML=scaleStudyFicha(p);openRight();statusEl.textContent=`${p.cell_id||'Célula'} · estudo de escala`;statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),1700);}
async function showScaleStudy(){if(activeStratifiedKey)hideStratified();const scale=document.getElementById('scaleStudyScale')?.value||'250',metric=document.getElementById('scaleStudyMetric')?.value||'n_E01',key='sc'+scale;await ensureScaleStudyMeta();activeScaleStudyMetric=metric;clearScaleStudyHighlight();if(activeSpatialKey)hideSpatialStructure();if(activeGridEvidenceKey)hideGridEvidence();if(activeScaleStudyKey&&activeScaleStudyKey!==key&&layers[activeScaleStudyKey])map.removeLayer(layers[activeScaleStudyKey]);activeScaleStudyKey=key;const layer=await ensureLayer(key);layer.setStyle(f=>scaleStudyStyle(f,key));if(!map.hasLayer(layer))layer.addTo(map);layer.bringToFront();statusEl.textContent='ESTUDO DE ESCALA ATIVO · malha sintética O00';statusEl.classList.remove('hide');setTimeout(()=>statusEl.classList.add('hide'),2200);updateLegend();}
