let statisticsBundle=null,activeStatisticsId=null;
function statisticsCell(value){if(value===null||value===undefined||String(value).trim()==='')return '<span class="stats-unknown">UNKNOWN</span>';const raw=String(value).trim();if(/^-?\d+(\.\d+)?$/.test(raw)&&raw.length<18){const number=Number(raw);return Number.isFinite(number)?number.toLocaleString('pt-BR',{maximumFractionDigits:4}):esc(raw);}return esc(raw);}
function renderStatisticsDataset(id){if(!statisticsBundle)return;const dataset=statisticsBundle.datasets.find(item=>item.id===id)||statisticsBundle.datasets[0];if(!dataset)return;activeStatisticsId=dataset.id;document.getElementById('statisticsDatasetTitle').textContent=dataset.label;document.getElementById('statisticsFamily').textContent=dataset.family;document.getElementById('statisticsRowCount').textContent=dataset.row_count+' linha'+(dataset.row_count===1?'':'s');document.getElementById('statisticsSource').textContent='Fonte · '+dataset.source;const head=dataset.columns.map(column=>'<th scope="col"><code>'+esc(column)+'</code></th>').join('');const body=dataset.rows.map(row=>'<tr>'+dataset.columns.map(column=>'<td>'+statisticsCell(row[column])+'</td>').join('')+'</tr>').join('');document.getElementById('statisticsTable').innerHTML='<table class="statistics-table"><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table>';document.querySelectorAll('#statisticsDatasets [data-statistics-id]').forEach(button=>button.classList.toggle('active',button.dataset.statisticsId===dataset.id));const select=document.getElementById('statisticsSelect');if(select)select.value=dataset.id;}
async function renderStatistics(){const status=document.getElementById('statisticsStatus');try{if(!statisticsBundle)statisticsBundle=await getJSON('data/statistics/statistics_v26.json');const list=document.getElementById('statisticsDatasets'),select=document.getElementById('statisticsSelect');if(list&&!list.children.length){list.innerHTML=statisticsBundle.datasets.map(item=>'<button type="button" data-statistics-id="'+esc(item.id)+'"><span>'+esc(item.family)+'</span><b>'+esc(item.label)+'</b><small>'+item.row_count+' linha'+(item.row_count===1?'':'s')+'</small></button>').join('');list.querySelectorAll('[data-statistics-id]').forEach(button=>button.addEventListener('click',()=>renderStatisticsDataset(button.dataset.statisticsId)));}if(select&&!select.children.length){select.innerHTML=statisticsBundle.datasets.map(item=>'<option value="'+esc(item.id)+'">'+esc(item.label)+'</option>').join('');select.addEventListener('change',()=>renderStatisticsDataset(select.value));}if(status)status.hidden=true;renderStatisticsDataset(activeStatisticsId||statisticsBundle.datasets[0]?.id);}catch(error){console.error(error);if(status){status.hidden=false;status.textContent='Não foi possível carregar os resumos estatísticos.';status.classList.add('error');}}}

let locationMarker=null,locationAccuracy=null;
function setLocationState(state,message){const button=document.getElementById('locateMe');if(button){button.dataset.state=state;button.setAttribute('aria-label',message);button.title=message;}statusEl.classList.remove('hide','ok','error');statusEl.classList.add(state==='error'?'error':'ok');statusEl.textContent=message;setTimeout(()=>statusEl.classList.add('hide'),state==='error'?4200:2400);}
function bindLocationEvents(){map.on('locationfound',event=>{if(locationMarker&&map.hasLayer(locationMarker))map.removeLayer(locationMarker);if(locationAccuracy&&map.hasLayer(locationAccuracy))map.removeLayer(locationAccuracy);locationAccuracy=L.circle(event.latlng,{radius:event.accuracy,color:'#006CB7',weight:1.5,fillColor:'#006CB7',fillOpacity:.1,interactive:false}).addTo(map);const icon=L.divIcon({className:'current-location-marker',html:'<span><img src="assets/img/mi-posicao-ms.svg" alt=""></span>',iconSize:[38,38],iconAnchor:[19,19]});locationMarker=L.marker(event.latlng,{icon,zIndexOffset:1200,keyboard:true,title:'Minha posição'}).addTo(map);locationMarker.bindTooltip('Minha posição · precisão aproximada '+Math.round(event.accuracy)+' m',{direction:'top'});setLocationState('found','Posição localizada · precisão aproximada '+Math.round(event.accuracy)+' m');});map.on('locationerror',event=>{setLocationState('error','Localização indisponível · verifique a permissão do navegador');console.warn(event.message||event);});}
function locateUser(){setLocationState('locating','Localizando sua posição');map.locate({setView:true,maxZoom:13,enableHighAccuracy:true,timeout:12000,maximumAge:30000});}

function findFeatureAt(key,latlng){const group=key&&layers[key];if(!group||!map.hasLayer(group))return null;const point=map.latLngToLayerPoint(latlng);let found=null;group.eachLayer(layer=>{if(found||!layer.feature)return;try{if(typeof layer._containsPoint==='function'&&layer._containsPoint(point))found=layer;}catch(error){}if(!found&&layer.getBounds?.().contains(latlng))found=layer;});return found;}
function openActiveCellAt(latlng){const candidates=[
 [activeRPKey,openResearchPriorityFeature],[activeSSKey,openStabilitySensitivityFeature],[activeQSKey,openQuestionSufficiencyFeature],[activeEKKey,openEffectiveKnowledgeFeature],[activeIRKey,openIndependenceFeature],[activeVTKey,openVerticalTemporalFeature],[activeStratifiedKey,openStratifiedFeature],[activeScaleStudyKey,openScaleStudyFeature],[activeSpatialKey,openSpatialStructureFeature],[activeGridEvidenceKey,openGridEvidenceFeature]
 ];for(const [key,open] of candidates){if(!key)continue;const layer=findFeatureAt(key,latlng);if(layer){open(layer.feature.properties||{},layer,key);return true;}}return false;}

function closeNavMenus(except=null){document.querySelectorAll('.nav-menu-trigger').forEach(trigger=>{const menu=document.getElementById(trigger.getAttribute('aria-controls'));const keep=menu===except;if(menu&&!keep)menu.hidden=true;if(!keep)trigger.setAttribute('aria-expanded','false');});}
function setupNavMenus(){document.querySelectorAll('.nav-menu-trigger').forEach(trigger=>{const menu=document.getElementById(trigger.getAttribute('aria-controls'));trigger.addEventListener('click',event=>{event.stopPropagation();const willOpen=menu.hidden;closeNavMenus(willOpen?menu:null);menu.hidden=!willOpen;trigger.setAttribute('aria-expanded',String(willOpen));});menu?.addEventListener('click',()=>closeNavMenus());});document.addEventListener('click',event=>{if(!event.target.closest('.nav-menu'))closeNavMenus();});}

let lastModalTrigger=null,documentViewerParentModal=null;
function openModal(id,trigger=null){const modal=document.getElementById(id);if(!modal)return;document.querySelectorAll('.modal:not([hidden])').forEach(other=>{if(other!==modal)other.hidden=true;});lastModalTrigger=trigger||document.activeElement;modal.hidden=false;document.body.classList.add('modal-open');closeNavMenus();if(id==='statsModal')renderStatistics();setTimeout(()=>modal.querySelector('.modal-close')?.focus(),0);}
function closeModal(modal,restoreFocus=true){if(!modal)return;modal.hidden=true;if(modal.id==='docViewerModal'&&documentViewerParentModal){const parent=document.getElementById(documentViewerParentModal);documentViewerParentModal=null;if(parent){parent.hidden=false;document.body.classList.add('modal-open');setTimeout(()=>parent.querySelector('.modal-close')?.focus(),0);return;}}if(!document.querySelector('.modal:not([hidden])'))document.body.classList.remove('modal-open');if(restoreFocus)lastModalTrigger?.focus?.();}
function setupModals(){document.querySelectorAll('[data-modal]').forEach(button=>button.addEventListener('click',event=>openModal(button.dataset.modal,event.currentTarget)));document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>closeModal(button.closest('.modal'))));document.querySelectorAll('.modal').forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)closeModal(modal);}));document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;const modal=document.querySelector('.modal:not([hidden])');if(modal)closeModal(modal);else closeNavMenus();});}

function openDocumentation(href,label,trigger){const frame=document.getElementById('docViewerFrame'),external=document.getElementById('docViewerExternal'),title=document.getElementById('docViewerTitle'),loading=document.getElementById('docViewerLoading');if(!frame||!external||!title)return;const currentModal=trigger?.closest?.('.modal:not([hidden])');documentViewerParentModal=currentModal&&currentModal.id!=='docViewerModal'?currentModal.id:null;title.textContent=label||'Documento';external.href=href;if(loading)loading.hidden=false;frame.src=href;openModal('docViewerModal',trigger);}
function setupDocumentationViewer(){const frame=document.getElementById('docViewerFrame'),loading=document.getElementById('docViewerLoading'),title=document.getElementById('docViewerTitle');frame?.addEventListener('load',()=>{if(loading)loading.hidden=true;try{const pageTitle=frame.contentDocument?.title?.trim();if(pageTitle&&title)title.textContent=pageTitle;}catch(error){}});document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest('a[href]');if(!link||link.hasAttribute('download')||link.closest('#docViewerModal'))return;const raw=link.getAttribute('href');if(!raw||raw.startsWith('#'))return;let url;try{url=new URL(raw,location.href);}catch(error){return;}const local=url.origin===location.origin&&url.pathname.toLowerCase().endsWith('.html')&&!url.pathname.toLowerCase().endsWith('/index.html');if(!local)return;event.preventDefault();const label=link.querySelector('strong')?.textContent?.trim()||link.textContent.trim()||'Documento';openDocumentation(raw,label,link);});}
function openRequestedModal(){const requested=new URLSearchParams(location.search).get('open');const allowed={stats:'statsModal',help:'helpModal',author:'authorModal',docs:'docsModal',methods:'methodModal'};if(allowed[requested])setTimeout(()=>openModal(allowed[requested]),80);}

function updateActiveLayerCount(){const count=[...document.querySelectorAll('[data-layer]')].filter(input=>input.checked).length;const label=document.getElementById('activeLayerCount');if(label)label.textContent=count+' ativa'+(count===1?'':'s');}
function setupLayerToolbar(){const groups=[...document.querySelectorAll('.layer-group')];document.querySelectorAll('.group-title').forEach(button=>{button.setAttribute('aria-expanded',String(button.closest('.layer-group').classList.contains('open')));button.addEventListener('click',()=>{const group=button.closest('.layer-group');group.classList.toggle('open');button.setAttribute('aria-expanded',String(group.classList.contains('open')));});});document.getElementById('expandLayerGroups')?.addEventListener('click',()=>groups.forEach(group=>{group.classList.add('open');group.querySelector('.group-title')?.setAttribute('aria-expanded','true');}));document.getElementById('collapseLayerGroups')?.addEventListener('click',()=>groups.forEach(group=>{group.classList.remove('open');group.querySelector('.group-title')?.setAttribute('aria-expanded','false');}));document.getElementById('layerSearch')?.addEventListener('input',event=>{const query=normalizeSearchText(event.target.value);groups.forEach(group=>{const match=!query||normalizeSearchText(group.textContent).includes(query);group.hidden=!match;if(query&&match){group.classList.add('open');group.querySelector('.group-title')?.setAttribute('aria-expanded','true');}});});updateActiveLayerCount();}
